import sys,numpy as np,json
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();s=r.spec();n=np.asarray(r.get_obs().meta['proprio']['now'],float);lay=s['proprio_layout'];names=s['kinematics']['joint_names'];q=np.array([n[lay.index(k)] for k in names]);lim={j['name']:j['position_limits'] for j in s['robot_spec']['joints']};lo=np.array([lim[k][0]+1e-3 for k in names]);hi=np.array([lim[k][1]-1e-3 for k in names]);q=np.clip(q,lo,hi);base=n[28:35];xyz=n[35:38].copy();q0=n[38:42].copy();rx=np.array([-.70710678,0,0,.70710678]);
def mul(a,b):
 x1,y1,z1,w1=a;x2,y2,z2,w2=b
 return np.array([w1*x2+x1*w2+y1*z2-z1*y2,w1*y2-x1*z2+y1*w2+z1*x2,w1*z2+x1*y2-y1*x2+z1*w2,w1*w2-x1*x2-y1*y2-z1*z2])
q1=mul(q0,rx);q1/=np.linalg.norm(q1);dot=np.dot(q0,q1)
if dot<0:q1=-q1;dot=-dot
def slerp(t):
 if dot>.9995:
  v=q0+t*(q1-q0);return v/np.linalg.norm(v)
 th=np.arccos(np.clip(dot,-1,1));return (np.sin((1-t)*th)*q0+np.sin(t*th)*q1)/np.sin(th)
def row(v):
 x=np.zeros(25);x[3:7]=v[:4];x[7:14]=v[4:11];x[14:16]=.07;x[16:23]=v[11:18];x[23:25]=.07;return x
A=[]
for t in [.125,.25,.375,.5]:
 pose=np.r_[xyz,slerp(t)];a=r.ik({'left_eef_link':pose.tolist()},seed=q.tolist(),base_pose=base.tolist(),max_iters=400)
 if not a.get('ok'):raise RuntimeError(('IK',t,a.get('error')))
 g=np.clip(np.asarray(a['q']),lo,hi);print('t',t,'dq',round(float(np.max(np.abs(g-q))),3),'err',a['error']['left_eef_link'])
 for u in np.linspace(1/6,1,6):A.append(row(q*(1-u)+g*u))
 q=g
res=r.submit('joint_position',np.stack(A),dt=1/30,video='frames');res.save('/app/output/pom_side_rotate1');n=np.asarray(res.proprio[-1]);print('META',json.dumps({k:res.meta.get(k) for k in ['done','clipped','control_steps_chunk','executed_rows']}));print('eef',np.round(n[35:42],3).tolist(),'grip',np.round(n[77:79],3).tolist(),'torque',np.round(n[99:103],1).tolist())
